Reproduction.Prepare:
$ErrorActionPreference = 'Stop'
$repo = (Resolve-Path (Join-Path $PSScriptRoot '../../..')).Path
Set-Location $repo
$sourceCases = Get-Content -LiteralPath (Join-Path (Split-Path $PSScriptRoot -Parent) 'csv-writer-buffers/full-cases.json') -Raw | ConvertFrom-Json -AsHashtable
$cases = [ordered]@{}
foreach ($key in ($sourceCases.Keys | Sort-Object)) {
    if ($sourceCases[$key].Method -eq 'Save') { $cases[$key] = $sourceCases[$key] }
}
if ($cases.Count -ne 39) { throw 'Unexpected complete synchronous stream-save matrix' }
foreach ($key in 'ToBytes-Plain-None-100000','ToBytes-Quoted-GZip-100000','SaveAsync-Plain-None-25000',
    'SaveFile-Plain-None-25000','WriteDataReader-Plain-None-25000','RowWriterFile-Plain-None-25000') {
    $cases[$key] = $sourceCases[$key]
}
