param([long] $Mask = 65535, [int] $Iterations = 24, [int] $Warmup = 32, [int] $Operations = 4,
    [string] $Cases = 'screen-cases.json', [string] $Label = 'screen-rotated', [switch] $IdenticalBaseline)
